create_order_preview.code:
import com.webcommander.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.orderPreviews().createOrderPreview(Map.of(
        "customer_id", 512, "delivery_type", "shipping",
        "products", List.of(Map.of("product_id", 101, "quantity", 2))));
Map<?, ?> order = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("order");
Map<?, ?> session = (Map<?, ?>) order.get("session");
System.out.println(session.get("session_id") + " " + session.get("status") + " " + session.get("expires_at"));
Map<?, ?> totals = (Map<?, ?>) order.get("totals");
System.out.println(totals.get("sub_total") + " " + totals.get("total_discount") + " " + totals.get("grand_total") + " " + totals.get("due"));

