import com.webcommander.client.ApiResponse;
import java.util.Map;

ApiResponse response = client.orderPreviews().confirmOrderPreview("PRV-3f2a9c41b7d80e65", Map.of(
        "send_email", false, "transaction_no", "TXN-ORDER-0001",
        "payment", Map.of("amount", 10.0, "payment_status", "success", "payment_method", "manual",
                "transaction_reference", "REF-0001", "transaction_date", "2026-11-05T06:12:00Z")));
Map<?, ?> order = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("order");
System.out.println(order.get("order_id") + " " + order.get("order_status") + " " + order.get("payment_status"));
System.out.println(order.get("grand_total") + " " + order.get("paid") + " " + order.get("due"));

